//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gIsurCd;
scwin.vScrenID = "ULDSTF20506.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_ST;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "DELIST_REAL_INVSTG_RSN_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_RSN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='DELIST_REAL_INVSTG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    var fileContents = $c.stf.trim($c.stf.getObjectValue(txb_FileContents));
    if (fileContents.length > 0) {
        $c.stf.showObj(mgrd_Grid, true);
        $c.stf.showObj(grd_Grid, false);
    } else {
        $c.stf.showObj(mgrd_Grid, false);
        $c.stf.showObj(grd_Grid, true);
    }
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        return;
    }
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var commitTpCd = "";
    if (js_market == "1") {
        commitTpCd = $c.stf.getObjectValue(cmb_Commit_Tp_Cd_KOSPI);
    } else {
        commitTpCd = $c.stf.getObjectValue(cmb_Commit_Tp_Cd);
    }
    var url = "/RealInvstg.do?SCREN_ID=ULDSTF20506.gfm&SCREN_PROCES_TP_CD=01&method=realInvstgDataList" + "&outputMessageId=REALINVSTG_FILE_SEARCH" + "&CommitTpCd=" + commitTpCd + "&SDate=" + $c.stf.getObjectValue(edt_SDate) + "&EDate=" + $c.stf.getObjectValue(edt_EDate) + "&LdMktTpCd=" + vMarketTpCd + "&IsurCd=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&SEARCH_RSLT_CONDITION=" + $c.stf.getObjectValue(cmb_Rslt) + "&DELIST_REAL_INVSTG_RSN_CD=" + $c.stf.getObjectValue(cmb_DELIST_REAL_INVSTG_RSN_CD) + "&searchKeyword=" + $c.stf.getObjectValue(txb_FileContents);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 함수
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = "";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].COM_NM);
        vIsurCd = arrPar[0].ISUR_CD;
    }
};




//파일 다운로드
scwin.fn_filedown = function(bzProcsNo, procsNo, dtlSeq, fileSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
};
scwin.img_COM_NM_onclick = function() {
    fn_GetPar = fn_GetParIsur;
    fn_SetPar = fn_SetParIsur;
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_ISUR_NM);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDSTF20506.gfm", SCREN_PROCS_TP_CD_07);
    //grd_Grid.GridToExcel("위원회별 심의내역 및 심사자료", "", "8");
    $c.data.downloadGridViewOffice(grd_Grid, "위원회별 심의내역 및 심사자료", "", 8, 0);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.elw.fn_searchCode();
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_SDate.text = cGetMinusDate2(vCurDate, 7);
    edt_SDate.setValue("20110101");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    if (js_market == "1") {
        $c.stf.showObj(cmb_Commit_Tp_Cd_KOSPI, true);
        $c.stf.showObj(cmb_Commit_Tp_Cd, false);
        cmb_Commit_Tp_Cd_KOSPI.BindColVal = "A";
    } else {
        $c.stf.showObj(cmb_Commit_Tp_Cd_KOSPI, false);
        $c.stf.showObj(cmb_Commit_Tp_Cd, true);
        cmb_Commit_Tp_Cd.BindColVal = "A";
    }
    cmb_DELIST_REAL_INVSTG_RSN_CD.BindColVal = "A";
    cmb_Rslt.BindColVal = "A";
    //cmb_Remk.BindColVal = "A";
    scwin.fn_list_sync();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == "ATTACH_FILE_NM") {
        var vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
        var listEligtyProcsCd = dts_List.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        var dtlSeq = dts_List.getCellData(row, "FILE_SEQ");
        var url = "/lstsrch/ULDSTF20506_FILE.gfm?BZ_PROCS_NO=" + vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + listEligtyProcsCd + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq;
        await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 조회", 100, 100, 850, 450, "window");
    }
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_ISUR_NM.setValue("");
    }
};
scwin.txb_FileContents_onkeydown = function() {
    if (event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.mgrd_Grid_OnLButtonDblClk = function(type, row, colid, x, y) {
    if (colid == "ATTACH_FILE_NM") {
        var bzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
        var procsNo = dts_List.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        var dtlSeq = dts_List.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        var fileSeq = dts_List.getCellData(row, "ATTACH_FILE_SEQ");
        $c.elw.fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq);
    }
};
